package com.catalogix.audit.service; import com.catalogix.audit.model.AuditEntry; import com.catalogix.audit.repository.AuditRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import tools.jackson.databind.json.JsonMapper; import java.time.Instant; import java.util.*; @Service public class AuditService{final AuditRepository repo;final JsonMapper mapper=new JsonMapper();public AuditService(AuditRepository r){repo=r;}@Transactional public void record(String routingKey,Map<?,?> payload){AuditEntry e=new AuditEntry();e.setAction(routingKey.toUpperCase(Locale.ROOT).replace('.','_'));String type=routingKey.contains(".")?routingKey.substring(0,routingKey.indexOf('.')):routingKey;e.setEntityType(type);Object id=payload.get("orderId");if(id==null)id=payload.get("id");if(id==null)id=payload.get("sellerId");e.setEntityId(id==null?null:String.valueOf(id));Object uid=payload.get("userId");if(uid instanceof Number n)e.setActorUserId(n.longValue());Object ts=payload.get("occurredAt");if(ts instanceof String){try{e.setOccurredAt(Instant.parse((String)ts));}catch(Exception ignored){}}try{String d=mapper.writeValueAsString(payload);e.setDetails(d.length()>1000?d.substring(0,1000):d);}catch(Exception ex){e.setDetails("payload-unavailable");}repo.save(e);}}
